        const core_id = core_entry.key_ptr.*;
        const core_info = core_entry.value_ptr.*;

        if (core_info.state == .power_gated) continue;

        // SZÁMOLD: hány entangled block van már ezen a core-on?
        var entangled_count: usize = 0;
        if (self.affinity_map.getPtr(core_id)) |core_blocks| {
            var entangle_iter = block.entangled_blocks.iterator();
            while (entangle_iter.next()) |ent_entry| {
                if (core_blocks.contains(ent_entry.key_ptr.*)) {
                    entangled_count += 1;
                }
            }
        }

        // Minél több entangled block van ott, annál "közelebb" van
        const distance = 1.0 / (1.0 + @as(f64, @floatFromInt(entangled_count)));
        if (distance < min_distance) {
            min_distance = distance;
            nearest_core = core_id;
        }
    }

    return nearest_core;
}


Ez nem random placement  ez locality optimization:[1]
 Ha BlockA és BlockB össze van fonva, ugyanazon a coreon kell lenniük (cache locality)
 Ha egy core túlterhelt, a rendszer automatikusan migrál másik corera

NUMA (NonUniform Memory Access) Analógia: Modern CPUk különböző corejai különböző távolságban vannak a memóriától. A Chaos Core explicit modellezi ezt.[5]



 4. Dynamic Task Scheduling: WorkStealing + Data Locality

 Priority Queue + Core Affinity Scoring

zig
pub fn scheduleTask(
    self: *DynamicTaskScheduler,
    cores: *AutoHashMap(usize, ProcessingCore),
    storage: *ContentAddressableStorage,
) !?struct { task_id: [32]u8, core_id: usize } {
    const task_opt = self.pending_tasks.removeOrNull();  // Legmagasabb prioritás
    if (task_opt == null) return null;

    var task = task_opt.?;

    // SCORE minden core-t
    var core_scores = AutoHashMap(usize, f64).init(self.allocator);
    defer core_scores.deinit();

    var core_iter = cores.iterator();
    while (core_iter.next()) |core_entry| {
        const core_id = core_entry.key_ptr.*;
        const core_info = core_entry.value_ptr.*;

        if (core_info.state == .power_gated) continue;

        var score: f64 = 0.0;

        // 1. DATA LOCALITY: Hány dependency van ezen a core-on?
        for (task.data_dependencies.items) |dep_id| {
            if (storage.containsBlock(dep_id)) {
                const nearest = storage.findNearestCore(dep_id, cores);
                if (nearest) |nearest_core| {
                    if (nearest_core == core_id) {
                        score += 10.0;  // NAGY bónusz ha itt van az adat
                    } else {
                        score += 1.0;   // Kis bónusz ha "közelben" van
                    }
                }
            }
        }

        // 2. LOAD BALANCING: Preferálja az idle core-okat
        const workload = core_info.getWorkload();
        score += (1.0 - workload) * 5.0;

        try core_scores.put(core_id, score);
    }

    // Válaszd a LEGJOBB score-t
    var best_core: usize = 0;
    var best_score: f64 = -std.math.inf(f64);
    var score_iter = core_scores.iterator();
    while (score_iter.next()) |entry| {
        const s = entry.value_ptr.*;
        if (s > best_score) {
            best_score = s;
            best_core = entry.key_ptr.*;
        }
    }

    task.assigned_core = best_core;
    task.start_time = std.time.nanoTimestamp();

    const task_id = task.task_id;
    try self.active_tasks.put(task_id, task);

    return .{ .task_id = task_id, .core_id = best_core };
}


Ez több mint Linux CFS (Completely Fair Scheduler):
 Dataaware: Figyelembe veszi, hogy hol van az adat (nem csak CPU time)
 Entanglementaware: Az összefonódott blokkok "gravitálnak" egymás felé
 Workloadbalanced: Nem túlterheli az egy coret

