pub fn buildFlowGraph(self: *DataFlowAnalyzer, tasks: []const TaskDescriptor) !void {
    for (tasks) |task| {
        const deps = task.data_dependencies.items;

        // MINDEN PÁROS KOMBINÁCIÓ
        var i: usize = 0;
        while (i < deps.len) : (i += 1) {
            const dep1 = deps[i];
            for (deps[i + 1 ..]) |dep2| {
                // Ha dep1 és dep2 együtt jelennek meg egy task-ban...
                // ...akkor valószínűleg KORRELÁLNAK

                var result1 = try self.flow_graph.getOrPut(dep1);
                if (!result1.found_existing) {
                    result1.value_ptr.* = BlockIdSet.init(self.allocator);
                }
                try result1.value_ptr.put(dep2, {});  // dep1 → dep2 edge

                var result2 = try self.flow_graph.getOrPut(dep2);
                if (!result2.found_existing) {
                    result2.value_ptr.* = BlockIdSet.init(self.allocator);
                }
                try result2.value_ptr.put(dep1, {});  // dep2 → dep1 edge (szimmetrikus)

                // SÚLY növelése
                var sorted_key: FlowEdgeKey = ...;
                var weight_entry = try self.flow_weights.getOrPut(sorted_key);
                if (!weight_entry.found_existing) {
                    weight_entry.value_ptr.* = 0.0;
                }
                weight_entry.value_ptr.* += 1.0;  // ← Minden co-occurrence növeli
            }
        }
    }
}


Ez nem supervised learning  ez unsupervised correlation discovery:[1]
 Ha BlockA és BlockB gyakran együtt használódnak, a súly nő
 Ha weight > threshold, automatikusan entanglelődnak
 Nincs explicit training  emergens viselkedés

Emberi Analógia: Amikor tanulsz programozni, eleinte "for loop" és "array" két külön fogalom. Később automatikusan asszociálnak  ha látod az egyiket, "felugrik" a másik. A Chaos Core ugyanezt tanulja.[3][2]



 6. Eviction Strategy: MultiPass, EntanglementAware

 Kétfázisú Eviction (NemEntangled → Entangled)

zig
pub fn evictLeastUsed(self: *ContentAddressableStorage, required_free: usize) !void {
    if (required_free == 0) return;

    // 1. Gyűjts minden blokkot eviction score-ral
    var blocks_to_sort: ArrayList(EvictionEntry) = .empty;
    defer blocks_to_sort.deinit(self.allocator);

    var iter = self.storage.iterator();
    while (iter.next()) |entry| {
        const block = entry.value_ptr.*;
        try blocks_to_sort.append(self.allocator, .{
            .id = block.block_id,
            .access_count = block.access_count,
            .last_access = block.last_access_time,
            .size = block.size,
            .entangled = block.state == .entangled,  // ← FONTOS!
        });
    }

    // 2. Rendezd: entangled UTOLJÁRA, kevés access ELŐSZÖR
    std.mem.sort(EvictionEntry, blocks_to_sort.items, {}, EvictionEntry.lessThan);

    // 3. KÉTFÁZISÚ EVICTION
    var freed: usize = 0;
    var pass: usize = 0;
    while (freed < required_free) : (pass += 1) {
        if (pass > 1) return error.OutOfMemory;  // Max 2 pass

        for (blocks_to_sort.items) |block_info| {
            if (freed >= required_free) break;

            // ELSŐ PASS: Csak nem-entangled blokkokat törölj
            if (pass == 0 and block_info.entangled) continue;

            // MÁSODIK PASS: Ha még mindig kell, törölj entangled-et is
            if (self.removeBlock(block_info.id)) |removed_size| {
                freed += removed_size;
            }
        }
    }
}


Védett Memória Koncepció:
 Pass 0: "Unalmas" (nementangled, kevés access) blokkok → törlés
 Pass 1: Ha még mindig kell hely, fontos (entangled) blokkok is törölhetők

Emberi Analógia: Ha helyet kell csinálnod a szobádban:
1. Első kör: Kidobod a szemetet, régi újságokat (lowpriority)
2. Második kör: Ha még mindig kell hely, fontos könyveket is elrakod (highpriority)

De soha nem dobod el azonnal a fontos dolgokat.[2][1]



